import { readFileSync } from "fs";
const root = "/home/user/ai-sdlc-agentic-workflows/kestrel/data/";
const csv = (f: string) => {
  const [h, ...rows] = readFileSync(root + f, "utf8").trim().split("\n");
  const k = h.split(",");
  return rows.map((r) => Object.fromEntries(r.split(",").map((v, j) => [k[j], v])));
};
const d = csv("deploys.csv"), inc = csv("incidents.csv");
const t = (x: string) => Date.parse(x);
const med = (a: number[]) => { const b = [...a].sort((x, y) => x - y), n = b.length; return n % 2 ? b[(n - 1) / 2] : (b[n / 2 - 1] + b[n / 2]) / 2; };
const mean = (a: number[]) => a.reduce((x, y) => x + y, 0) / a.length;
const f1 = (x: number) => x.toFixed(1);
function summ(rows: any[], label: string) {
  if (!rows.length) return console.log(label, "none");
  const lt = rows.map((r) => (t(r.deployed_at) - t(r.committed_at)) / 36e5);
  const f = rows.filter((r) => r.incident_id).length;
  console.log(label, rows.length, "deploys | lead h med", f1(med(lt)), "mean", f1(mean(lt)), "min", f1(Math.min(...lt)), "max", f1(Math.max(...lt)), "| fail", f, f1((100 * f) / rows.length) + "%");
}
summ(d, "ALL");
const m: Record<string, any[]> = {};
for (const r of d) (m[r.deployed_at.slice(0, 7)] ??= []).push(r);
for (const k of Object.keys(m).sort()) summ(m[k], k);
const span = (t(d.at(-1)!.deployed_at) - t(d[0].deployed_at)) / 864e5;
console.log("span days", f1(span), "per week", (d.length / (span / 7)).toFixed(2));
const cut = t("2026-10-26T10:30:00Z");
summ(d.filter((r) => t(r.deployed_at) < cut), "pre-adoption deploys");
summ(d.filter((r) => t(r.deployed_at) >= cut), "post-adoption deploys");
summ(d.filter((r) => t(r.committed_at) >= cut), "post-adoption commits");
const tt = inc.map((r) => (t(r.resolved_at) - t(r.started_at)) / 6e4);
console.log("restore min med", f1(med(tt)), "mean", f1(mean(tt)), "min", f1(Math.min(...tt)), "max", f1(Math.max(...tt)));
const dd = Object.fromEntries(d.map((r) => [r.deploy_id, r]));
console.log(inc.map((r) => `${r.incident_id} ${r.deploy_id} restore ${Math.round((t(r.resolved_at) - t(r.started_at)) / 6e4)}m after-deploy ${f1((t(r.started_at) - t(dd[r.deploy_id].deployed_at)) / 36e5)}h`).join("\n"));

